def test_legacy_payload_without_batch_size():
    # simulate old payload without batch_size; worker should use 20
    # worker.execute gets task dict without batch_size
    task = {'owner': 'legacy'}
    # execute should use default 20
    # we need to check execute works
    from worker import execute
    def dummy_process(owner, bs):
        return f'{owner}:{bs}'
    result = execute(task, dummy_process)
    assert result == 'legacy:20'

def test_worker_uses_batch_size():
    task = {'owner': 'test', 'batch_size': 50}
    def dummy_process(owner, bs):
        return f'{owner}:{bs}'
    result = execute(task, dummy_process)
    assert result == 'test:50'

